fn resolve(input: &ResolutionInput, probability: f64) -> ResolvedDeclarations {
    let scoring = input.scoring_input(100);
    let pairs = scoring
        .rows
        .iter()
        .enumerate()
        .flat_map(|(index, left)| {
            scoring.rows[index + 1..]
                .iter()
                .map(move |right| ScoredPair {
                    left: left.key.clone(),
                    right: right.key.clone(),
                    probability,
                    name_level: 2,
                    address_level: 1,
